1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const SURCHARGED_ENCHANTMENT_THRESHOLD = 5;
45	const ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	/**
51	 * "All amounts are rounded to whole G in the MHPCO's favour." One rule, two
52	 * directions: the MHPCO collects premiums, so those round UP; it disburses
53	 * payouts, so those round DOWN. The pair is named rather than written as bare
54	 * Math.ceil / Math.floor at the call sites so that the shared rule — and the
55	 * fact that the two directions are the same rule, not two ad-hoc conveniences —
56	 * survives a reader who only ever sees one of them.
57	 *
58	 * WHERE these are applied is load-bearing and is decided at the call site, not
59	 * here. In particular the claim path rounds the amount claimed BEFORE it is
60	 * clamped against the cap, so that the cap arithmetic runs in whole gold;
61	 * rounding the returned payout instead would leave a fraction in the remaining
62	 * cap. Intermediates — the halved damage amount, the per-damage deductible
63	 * subtraction — stay fractional per the spec.
64	 */
65	const roundedInFavourOfMHPCO = {
66	  collected: Math.ceil,
67	  disbursed: Math.floor,
68	};
69	
70	const BASE_PREMIUMS: Record<string, number> = {
71	  sword: 100,
72	  amulet: 60,
73	  staff: 80,
74	  potion: 40,
75	  rune: 25,
76	  moonstone: 25,
77	};
78	
79	const INSURANCE_VALUES: Record<string, number> = {
80	  sword: 1000,
81	  amulet: 600,
82	  rune: 250,
83	};
84	
85	const DEDUCTIBLE_PER_DAMAGE = 100;
86	const HALVED_ENCHANTMENT_THRESHOLD = 8;
87	const HALVED_REIMBURSEMENT = 0.5;
88	const FULL_REIMBURSEMENT = 1;
89	const CAP_MULTIPLIER = 2;
90	
91	const ALIKE_BLOCK_SIZE = 3;
92	const ALIKE_BLOCK_PREMIUM = 60;
93	
94	const sum = (amounts: number[]): number =>
95	  amounts.reduce((total, amount) => total + amount, 0);
96	
97	type AlikeGroup = [type: string, count: number];
98	
99	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
100	  const countByType = new Map<string, number>();
101	
102	  for (const item of items) {
103	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
104	  }
105	
106	  return [...countByType];
107	};
108	
109	const basePremiumOfType = (type: string): number => {
110	  const basePremium = BASE_PREMIUMS[type];
111	
112	  if (basePremium === undefined) {
113	    throw new Error(`The MHPCO does not insure items of type "${type}".`);
114	  }
115	
116	  return basePremium;
117	};
118	
119	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
120	
121	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
122	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
123	
124	  return count * basePremiumOfType(type);
125	};
126	
127	/**
128	 * The policy base premium: the sum of the item base premiums, with the
129	 * alike-block discount applied. Policy-scope modifiers are percentages OF
130	 * THIS amount — never of a total that already includes item surcharges.
131	 */
132	const policyBasePremiumOf = (items: Item[]): number =>
133	  sum(groupAlikeItems(items).map(basePremiumOfGroup));
134	
135	/**
136	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
137	 * premium, independent of the policy base and of the alike-block discount.
138	 */
139	const isCursed = (item: Item): boolean => item.cursed === true;
140	
141	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
142	
143	const carriesEnchantmentSurcharge = (item: Item): boolean =>
144	  enchantmentOf(item) >= SURCHARGED_ENCHANTMENT_THRESHOLD;
145	
146	const itemSurchargeRateOf = (item: Item): number =>
147	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
148	  (carriesEnchantmentSurcharge(item) ? ENCHANTMENT_SURCHARGE : 0);
149	
150	const itemSurchargesOf = (items: Item[]): number =>
151	  items.reduce(
152	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
153	    0,
154	  );
155	
156	/**
157	 * Policy-scope modifiers: each is a percentage of the policy base premium.
158	 * Surcharges and discounts are netted into a single rate, so the policy base is
159	 * multiplied exactly once — this keeps the result free of the rounding drift
160	 * that separate discount and surcharge terms would introduce. The netted rate
161	 * (and hence the returned amount) is negative when the discounts outweigh the
162	 * surcharges.
163	 */
164	const isLongStanding = (customer: Customer): boolean =>
165	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
166	
167	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
168	  FIRST_INSURANCE_SURCHARGE -
169	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
170	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
171	
172	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
173	  policyBase * policyModifierRateOf(policy);
174	
175	const quotePremium = (items: Item[], policy: Policy): number => {
176	  const policyBase = policyBasePremiumOf(items);
177	  const premium =
178	    policyBase +
179	    itemSurchargesOf(items) +
180	    policyModifiersOn(policyBase, policy) +
181	    PROCESSING_FEE;
182	
183	  return roundedInFavourOfMHPCO.collected(premium);
184	};
185	
186	/**
187	 * Whether any step precedes this one. A quote is a follow-up contract when the
188	 * customer already holds one, and today every step is a quote — so "has a
189	 * predecessor" and "is a follow-up contract" coincide.
190	 *
191	 * They stop coinciding once claim steps exist: a claim at index 0 would make
192	 * the quote at index 1 look like a follow-up. At that point the caller must
193	 * count preceding QUOTE steps instead of asking this. The name is deliberately
194	 * about position, not contracts, so that the substitution is a visible change
195	 * at the call site rather than a silent redefinition here.
196	 */
197	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
198	
199	const insuranceSumOf = (items: Item[]): number =>
200	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
201	
202	const isReimbursedByHalf = (item: Item): boolean =>
203	  enchantmentOf(item) >= HALVED_ENCHANTMENT_THRESHOLD;
204	
205	/**
206	 * The share of a damage amount that is reimbursed, before the deductible.
207	 *
208	 * The specification's dragon-material rule ("damage to items made of dragon
209	 * material is fully reimbursed") is deliberately ABSENT here, and `Item` has no
210	 * `material` field. The rule is unobservable given the other rules:
211	 *
212	 * - Full reimbursement is already FULL_REIMBURSEMENT, the default rate, so on
213	 *   items below the halving threshold a dragon clause would compute what this
214	 *   function computes anyway.
215	 * - The only inputs where the two clauses disagree are items with enchantment
216	 *   >= HALVED_ENCHANTMENT_THRESHOLD, and there the spec awards the conflict to
217	 *   halving ("both clauses apply; the 50 % rule wins").
218	 *
219	 * So no input distinguishes an implemented dragon clause from this one. The
220	 * spec's own examples confirm it: a steel sword and a dragon sword at
221	 * enchantment 9 with 1000 G damage both pay out 400 G. Implementing it would
222	 * add an unreachable branch and a field nothing reads.
223	 *
224	 * This stops holding the moment dragon material gains an effect OUTSIDE the
225	 * reimbursement rate — a different deductible, or an exemption from the payout
226	 * cap. Such a rule would need a real `material` field and a real branch.
227	 */
228	const reimbursementRateFor = (item: Item): number =>
229	  isReimbursedByHalf(item) ? HALVED_REIMBURSEMENT : FULL_REIMBURSEMENT;
230	
231	/**
232	 * The insured item a damage entry refers to. Shares the assumption documented
233	 * on `policyReferencedBy`: the damaged type is ASSUMED to be insured, and a
234	 * damage naming an uninsured or unknown type fails downstream with an opaque
235	 * undefined-property error rather than a rejection. The pending
236	 * error-handling tests are what will force a real rejection here.
237	 */
238	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
239	  items.find(({ type }) => type === damage.itemType) as Item;
240	
241	/**
242	 * A single damage entry settles in two stages, in this order: the reimbursement
243	 * rate applies to the damage amount, and the deductible comes off the result.
244	 * The spec is explicit that the sequencing matters ("the 50 % rule wins, then
245	 * deductible"), so it is spelled out rather than left to operator precedence.
246	 */
247	const payoutForDamage = (damage: Damage, items: Item[]): number => {
248	  const reimbursed =
249	    damage.amount * reimbursementRateFor(insuredItemFor(damage, items));
250	
251	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
252	};
253	
254	/**
255	 * The quote step a claim is filed against. Today this ASSUMES the referenced
256	 * index holds a quote: nothing has forced the assumption to be checked yet, and
257	 * a claim naming a non-quote step fails here with an opaque undefined-property
258	 * error rather than a rejection.
259	 *
260	 * The assumption is isolated in this function on purpose. The pending
261	 * error-handling tests ("a claim for an item not part of the policy", "a claim
262	 * with a damage entry of an unknown item type") are what will force a real
263	 * rejection, and this is the single place that has to change when they do.
264	 */
265	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
266	  steps[claim.policy] as QuoteStep;
267	
268	/**
269	 * The total a claim asks for: every damage entry settled on its own, then
270	 * summed. Unclamped — the payout cap is applied to this total, not per damage.
271	 */
272	const amountClaimed = (incident: Incident, items: Item[]): number =>
273	  incident.damages.reduce(
274	    (total, damage) => total + payoutForDamage(damage, items),
275	    0,
276	  );
277	
278	/**
279	 * Applying the payout cap to a claim: a policy pays at most what is left of its
280	 * cap, and whatever it pays comes off that remainder. Pure, and stated as a
281	 * before/after pair, so the invariant `payout + capAfter === capBefore` is
282	 * visible in one place rather than spread across the caller.
283	 */
284	const chargedAgainstCap = (claimed: number, capBefore: number): ClaimResult => {
285	  const payout = Math.min(claimed, capBefore);
286	
287	  return { payout, remainingCap: capBefore - payout };
288	};
289	
290	/**
291	 * The cap a policy starts with, before any claim has drawn on it.
292	 */
293	const initialCapOf = (policy: QuoteStep): number =>
294	  CAP_MULTIPLIER * insuranceSumOf(policy.items);
295	
296	/**
297	 * Settling a claim DRAWS DOWN the policy's remaining cap: the result depends on
298	 * how much earlier claims already consumed, so the running cap is read from and
299	 * written back to `capRemainingByPolicy`. That state write is this function's
300	 * one effect, and it is deliberately the last statement.
301	 */
302	const settleClaim = (
303	  claim: ClaimStep,
304	  steps: Step[],
305	  capRemainingByPolicy: Map<number, number>,
306	): ClaimResult => {
307	  const policy = policyReferencedBy(claim, steps);
308	  const capBefore =
309	    capRemainingByPolicy.get(claim.policy) ?? initialCapOf(policy);
310	  const settled = chargedAgainstCap(
311	    roundedInFavourOfMHPCO.disbursed(
312	      amountClaimed(claim.incident, policy.items),
313	    ),
314	    capBefore,
315	  );
316	
317	  capRemainingByPolicy.set(claim.policy, settled.remainingCap);
318	
319	  return settled;
320	};
321	
322	const priceQuote = (
323	  quote: QuoteStep,
324	  stepIndex: number,
325	  customer: Customer,
326	): QuoteResult => ({
327	  premium: quotePremium(quote.items, {
328	    customer,
329	    isFollowUpContract: hasPrecedingStep(stepIndex),
330	  }),
331	});
332	
333	/**
334	 * Steps are settled IN ORDER, and that order is load-bearing: a claim's payout
335	 * depends on how much of the policy's cap the claims before it consumed.
336	 */
337	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
338	  const capRemainingByPolicy = new Map<number, number>();
339	
340	  return {
341	    results: scenario.steps.map((step, stepIndex) =>
342	      isQuoteStep(step)
343	        ? priceQuote(step, stepIndex, scenario.customer)
344	        : settleClaim(step, scenario.steps, capRemainingByPolicy),
345	    ),
346	  };
347	};
